class Money:
    # Amount of money stored as an integer number of cents.

    def __init__(self, cents=0):
        self.cents = int(cents)

    def __repr__(self):
        return 'Money(%d)' % self.cents

    def __eq__(self, other):
        if isinstance(other, Money):
            return self.cents == other.cents
        return NotImplemented

    def __ne__(self, other):
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result

    def __hash__(self):
        return hash(self.cents)

    def __add__(self, other):
        if isinstance(other, Money):
            return Money(self.cents + other.cents)
        return NotImplemented

    def __sub__(self, other):
        if isinstance(other, Money):
            return Money(self.cents - other.cents)
        return NotImplemented

    def __neg__(self):
        return Money(-self.cents)

    def __str__(self):
        sign = '-' if self.cents < 0 else ''
        whole, frac = divmod(abs(self.cents), 100)
        return '%s$%s.%02d' % (sign, format(whole, ','), frac)

    def split(self, n):
        if n <= 0:
            raise ValueError('cannot split into %r parts' % (n,))
        sign = -1 if self.cents < 0 else 1
        q, r = divmod(abs(self.cents), n)
        parts = [sign * (q + 1)] * r + [sign * q] * (n - r)
        return [Money(c) for c in parts]
